function validate([aliceValues, bobValues]) {
  if (aliceValues.length !== bobValues.length) return 'Both arrays need the same length.';
  if (aliceValues.length < 1 || aliceValues.length > 100000) return 'There must be 1 to 10^5 stones.';
  if (aliceValues.some(v => !Number.isInteger(v) || v < 1 || v > 100)) return 'Each of aliceValues is an integer from 1 to 100.';
  if (bobValues.some(v => !Number.isInteger(v) || v < 1 || v > 100)) return 'Each of bobValues is an integer from 1 to 100.';
  return null;
}

