function stoneGameVI(aliceValues, bobValues) {
  const n = aliceValues.length;
  const order = Array.from({ length: n }, (_, i) => i);
  order.sort((i, j) => (aliceValues[j] + bobValues[j]) - (aliceValues[i] + bobValues[i]));
  let diff = 0;

  for (let turn = 0; turn < n; turn++) {
    const stone = order[turn];
    if (turn % 2 === 0) {
      diff += aliceValues[stone];
    } else {
      diff -= bobValues[stone];
    }
  }

  if (diff > 0) return 1;
  if (diff < 0) return -1;
  return 0;
}

