function stoneGameVI(aliceValues, bobValues) {
  // Exhaustive game search: best(mask) is the best (mover's score - other's score) on the stones left.
  const n = aliceValues.length;
  const memo = new Map();
  const best = (mask) => {
    if (mask === (1 << n) - 1) return 0;
    if (memo.has(mask)) return memo.get(mask);
    let taken = 0;
    for (let i = 0; i < n; i++) if (mask & (1 << i)) taken++;
    const values = taken % 2 === 0 ? aliceValues : bobValues;
    let result = -Infinity;
    for (let i = 0; i < n; i++) {
      if (mask & (1 << i)) continue;
      result = Math.max(result, values[i] - best(mask | (1 << i)));
    }
    memo.set(mask, result);
    return result;
  };
  const margin = best(0);
  return margin > 0 ? 1 : margin < 0 ? -1 : 0;
}

