function generate(rand, size) {
  if (size === 'large') {
    const n = 2000;
    const aliceValues = Array.from({ length: n }, () => 1 + Math.floor(rand() * 100));
    const bobValues = Array.from({ length: n }, () => 1 + Math.floor(rand() * 100));
    return [aliceValues, bobValues];
  }
  const n = 1 + Math.floor(rand() * 9);
  const top = rand() < 0.6 ? 1 + Math.floor(rand() * 4) : 100;
  const aliceValues = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  const bobValues = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  return [aliceValues, bobValues];
}
